using System.Collections.ObjectModel;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
using KhanBabaPos.Wpf.Services;
namespace KhanBabaPos.Wpf;
public sealed class SalesReportsWindow:Window
{
 readonly SalesReportService service=new();readonly ObservableCollection<DailySalesReport> rows=[];
 readonly DatePicker from=new(){SelectedDate=DateTime.Today};readonly DatePicker to=new(){SelectedDate=DateTime.Today};
 readonly DataGrid grid=new(){AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,EnableRowVirtualization=true,RowHeight=36};
 readonly TextBlock sales=new(),purchases=new(),expenses=new(),net=new(),status=new();
 public SalesReportsWindow(){Title="Sales Reports | Khan Baba POS";Width=1180;Height=740;MinWidth=950;MinHeight=580;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=Brushes.WhiteSmoke;Configure();Content=Layout();Loaded+=async(_,_)=>await LoadAsync();}
 void Configure(){grid.ItemsSource=rows;grid.Columns.Add(new DataGridTextColumn{Header="Date",Binding=new System.Windows.Data.Binding("Date"),Width=130});grid.Columns.Add(new DataGridTextColumn{Header="Net Sales",Binding=new System.Windows.Data.Binding("Sales"){StringFormat="N2"},Width=140});grid.Columns.Add(new DataGridTextColumn{Header="Purchases",Binding=new System.Windows.Data.Binding("Purchases"){StringFormat="N2"},Width=140});grid.Columns.Add(new DataGridTextColumn{Header="Expenses",Binding=new System.Windows.Data.Binding("Expenses"){StringFormat="N2"},Width=140});grid.Columns.Add(new DataGridTextColumn{Header="Discount",Binding=new System.Windows.Data.Binding("Discount"){StringFormat="N2"},Width=120});grid.Columns.Add(new DataGridTextColumn{Header="Returns",Binding=new System.Windows.Data.Binding("Returned"){StringFormat="N2"},Width=120});grid.Columns.Add(new DataGridTextColumn{Header="Net Activity",Binding=new System.Windows.Data.Binding("NetActivity"){StringFormat="N2"},Width=140});grid.SetValue(VirtualizingPanel.IsVirtualizingProperty,true);grid.SetValue(VirtualizingPanel.VirtualizationModeProperty,VirtualizationMode.Recycling);ScrollViewer.SetCanContentScroll(grid,true);}
 UIElement Layout(){var root=new DockPanel{Margin=new Thickness(20)};var header=new DockPanel{LastChildFill=false,Margin=new Thickness(0,0,0,14)};var title=new StackPanel();title.Children.Add(new TextBlock{Text="Sales Performance",FontSize=25,FontWeight=FontWeights.Bold,Foreground=Brushes.DarkSlateGray});title.Children.Add(new TextBlock{Text="Date-wise net sales, purchases and expenses from saved transactions.",Foreground=Brushes.DimGray,Margin=new Thickness(0,4,0,0)});header.Children.Add(title);var refresh=Btn("Refresh");refresh.Click+=async(_,_)=>await LoadAsync();DockPanel.SetDock(refresh,Dock.Right);header.Children.Add(refresh);DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
 var filters=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,0,14),VerticalAlignment=VerticalAlignment.Center};filters.Children.Add(new TextBlock{Text="From",VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,6,0)});from.Width=145;filters.Children.Add(from);filters.Children.Add(new TextBlock{Text="To",VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(14,0,6,0)});to.Width=145;filters.Children.Add(to);var apply=Btn("Apply Range");apply.Click+=async(_,_)=>await LoadAsync();filters.Children.Add(apply);DockPanel.SetDock(filters,Dock.Top);root.Children.Add(filters);
 var cards=new UniformGrid{Columns=4,Rows=1,Margin=new Thickness(0,0,0,12)};cards.Children.Add(Metric("Net Sales",sales));cards.Children.Add(Metric("Purchases",purchases));cards.Children.Add(Metric("Expenses",expenses));cards.Children.Add(Metric("Net Activity",net));DockPanel.SetDock(cards,Dock.Top);root.Children.Add(cards);
 var note=new TextBlock{Text="Net Activity = Net Sales − Purchases − Expenses. This is a comparison metric, not accounting profit or cash received.",Foreground=Brushes.DimGray,FontSize=11,Margin=new Thickness(0,0,0,8)};DockPanel.SetDock(note,Dock.Top);root.Children.Add(note);DockPanel.SetDock(status,Dock.Bottom);status.Margin=new Thickness(0,8,0,0);root.Children.Add(status);root.Children.Add(grid);return root;}
 static Border Metric(string label,TextBlock value){value.FontSize=19;value.FontWeight=FontWeights.Bold;var p=new StackPanel();p.Children.Add(new TextBlock{Text=label,Foreground=Brushes.DimGray});p.Children.Add(value);return new Border{Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(220,229,224)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(8),Padding=new Thickness(14),Margin=new Thickness(0,0,8,0),Child=p};}
 static Button Btn(string s)=>new(){Content=s,Padding=new Thickness(12,8,12,8),Margin=new Thickness(10,0,0,0)};
 async Task LoadAsync(){try{if(from.SelectedDate is null||to.SelectedDate is null)throw new InvalidOperationException("Select both report dates.");var result=await service.GetAsync(from.SelectedDate.Value,to.SelectedDate.Value);rows.Clear();foreach(var x in result.Days)rows.Add(x);sales.Text=$"Rs. {result.Sales:N2}";purchases.Text=$"Rs. {result.Purchases:N2}";expenses.Text=$"Rs. {result.Expenses:N2}";net.Text=$"Rs. {result.NetActivity:N2}";status.Text=$"{result.SalesCount:N0} sale(s) • Discount Rs. {result.Discount:N2} • Returns Rs. {result.Returned:N2} • {rows.Count:N0} date(s)";}catch(Exception e){status.Text="Report load failed: "+e.Message;}}
}